constraints:
1 <= N <= 10^{5}
1 <= k <= 10^{5}

expected time complexity: O(n)
expected auxiliary space: O(n)

standard_solution_code:
class Solution:

	def partition(self, head, x):
		less = []
		gre = []
		eq = []
		tmp = head
		while tmp:
			if tmp.data < x:
				less.append(tmp.data)
			elif tmp.data == x:
				eq.append(tmp.data)
			elif tmp.data > x:
				gre.append(tmp.data)
			tmp = tmp.next
		less = less + eq + gre
		head = None
		tmp = None
		for i in less:
			if head is None:
				node = Node(i)
				node.next = None
				head = node
				tmp = node
			else:
				node = Node(i)
				tmp.next = node
				tmp = node
		return head
